package markdown

import (
	"fmt"
	"strings"
)

// Render translates markdown to HTML.
//
// Refactoring note: the original implementation scanned the input one byte at
// a time while juggling several pieces of state (header level, list depth,
// "header entered" flag, ...). The rewrite processes the input line by line
// and dispatches each line to a small renderer for the block it starts:
// a header, a list item, or a paragraph. Consecutive list items are grouped
// into a single <ul> element.
func Render(markdown string) string {
	// A trailing newline at the end of the input does not start a new
	// block; drop it so it does not render as an empty paragraph.
	markdown = strings.TrimSuffix(markdown, "\n")

	var html strings.Builder
	inList := false

	for _, line := range strings.Split(markdown, "\n") {
		if inList && !isListItem(line) {
			html.WriteString("</ul>")
			inList = false
		}

		switch {
		case isHeader(line):
			html.WriteString(renderHeader(line))
		case isListItem(line):
			if !inList {
				html.WriteString("<ul>")
				inList = true
			}
			html.WriteString(renderListItem(line))
		default:
			html.WriteString(renderParagraph(line))
		}
	}

	if inList {
		html.WriteString("</ul>")
	}

	return html.String()
}

// isHeader reports whether line starts a header, i.e. it begins with
// one to six '#' characters. Seven or more '#' characters are not a
// valid header level and are treated as plain paragraph text.
func isHeader(line string) bool {
	level := headerLevel(line)
	return level >= 1 && level <= 6
}

// headerLevel counts the leading '#' characters in line.
func headerLevel(line string) int {
	level := 0
	for level < len(line) && line[level] == '#' {
		level++
	}
	return level
}

// renderHeader renders a header line as <hN>text</hN>, dropping the
// single space that separates the '#' marks from the text.
func renderHeader(line string) string {
	level := headerLevel(line)
	text := strings.TrimPrefix(line[level:], " ")
	return fmt.Sprintf("<h%d>%s</h%d>", level, renderEmphasis(text), level)
}

// isListItem reports whether line starts an unordered list item.
func isListItem(line string) bool {
	return strings.HasPrefix(line, "* ")
}

// renderListItem renders a list item line as <li>text</li>.
func renderListItem(line string) string {
	return "<li>" + renderEmphasis(strings.TrimPrefix(line, "* ")) + "</li>"
}

// renderParagraph renders a plain line as <p>text</p>.
func renderParagraph(line string) string {
	return "<p>" + renderEmphasis(line) + "</p>"
}

// renderEmphasis converts the first __...__ pair to <strong> and the
// first _..._ pair to <em>, mirroring the original implementation,
// which replaced at most one pair of each marker in the input.
func renderEmphasis(text string) string {
	text = strings.Replace(text, "__", "<strong>", 1)
	text = strings.Replace(text, "__", "</strong>", 1)
	text = strings.Replace(text, "_", "<em>", 1)
	text = strings.Replace(text, "_", "</em>", 1)
	return text
}
